;
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-estar-hay"] = {"version":1,"id":"a1-verbs-estar-hay","topic":"a1-verbs-estar-hay","level":"A1","title":"Stop: estar and hay","passScore":3,"items":[{"id":"a1-verbs-estar-hay-q1","type":"multiple-choice","kind":"form","prompt":"Yo ___ en la oficina.","options":["soy","estoy","hay","está"],"correct":1,"explanation":"Where you are takes estar: estoy.","optionNotes":["Location takes estar, not ser.",null,"Hay means “there is”.","Está is for él, ella, usted."]},{"id":"a1-verbs-estar-hay-q2","type":"multiple-choice","kind":"form","prompt":"___ un supermercado en mi calle.","options":["Está","Es","Hay","Están"],"correct":2,"explanation":"Something new with un takes hay: hay un supermercado.","optionNotes":["Está goes with a known thing (el supermercado).","Ser is not used for where things are.",null,"Están is plural and needs a known thing."]},{"id":"a1-verbs-estar-hay-q3","type":"multiple-choice","kind":"form","prompt":"¿Dónde ___ las llaves?","options":["hay","son","está","están"],"correct":3,"explanation":"A known thing (las llaves) takes estar, plural: están.","optionNotes":["Hay is for something new (un, dos…), not for las llaves.","Location takes estar.","Las llaves is plural.",null]},{"id":"a1-verbs-estar-hay-q4","type":"multiple-choice","kind":"form","prompt":"Ana ___ muy cansada hoy.","options":["está","es","hay","esta"],"correct":0,"explanation":"A state now takes estar: está (with an accent).","optionNotes":[null,"Being tired now is a state: estar.","Hay means “there is”.","Esta without an accent means “this”."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-gustar"] = {"version":1,"id":"a1-verbs-gustar","topic":"a1-verbs-gustar","level":"A1","title":"Stop: gustar","passScore":3,"items":[{"id":"a1-verbs-gustar-q1","type":"multiple-choice","kind":"form","prompt":"___ gusta el cine. (I like movies.)","options":["Yo","Me","Mi","Mí"],"correct":1,"explanation":"The person who likes something is shown by the pronoun me, te, le, nos, os, les: Me gusta el cine.","optionNotes":["Yo is a subject pronoun, but with gustar the subject is the thing you like.",null,"Mi means “my”.","Mí is used after a: a mí me gusta."]},{"id":"a1-verbs-gustar-q2","type":"multiple-choice","kind":"form","prompt":"Me ___ los libros de historia.","options":["gusta","gusto","gustan","gustamos"],"correct":2,"explanation":"Los libros is plural, and the verb agrees with the thing you like: gustan.","optionNotes":["Gusta is for one thing or an action.","Gusto would mean “I am pleasing”.",null,"The verb does not agree with the person who likes."]},{"id":"a1-verbs-gustar-q3","type":"multiple-choice","kind":"form","prompt":"A Pedro ___ gusta nadar.","options":["se","lo","él","le"],"correct":3,"explanation":"For he, she and usted the pronoun is le: A Pedro le gusta nadar.","optionNotes":["Se is a reflexive pronoun.","Lo is a direct object pronoun.","Él is a subject pronoun.",null]},{"id":"a1-verbs-gustar-q4","type":"multiple-choice","kind":"function","prompt":"—No me gusta el invierno.\n—___ (Me neither.)","options":["A mí también.","Me también.","A mí tampoco.","Yo tampoco gusto."],"correct":2,"explanation":"To agree with a negative sentence, use tampoco. With gustar the answer starts with a mí.","optionNotes":["También agrees with a positive sentence.","Me cannot stand alone; say a mí.",null,"The person is not the subject of gustar."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-ir-a-infinitive"] = {"version":1,"id":"a1-verbs-ir-a-infinitive","topic":"a1-verbs-ir-a-infinitive","level":"A1","title":"Stop: ir a + infinitive","passScore":3,"items":[{"id":"a1-verbs-ir-a-infinitive-q1","type":"multiple-choice","kind":"form","prompt":"Mañana yo ___ estudiar.","options":["voy","voy a","va a","vamos a"],"correct":1,"explanation":"Ir a + infinitive: voy a estudiar.","optionNotes":["You need a between ir and the infinitive.",null,"Va is for él, ella, usted.","Vamos is for nosotros."]},{"id":"a1-verbs-ir-a-infinitive-q2","type":"multiple-choice","kind":"form","prompt":"¿Qué ___ a hacer este fin de semana? (tú)","options":["vas","va","voy","vais"],"correct":0,"explanation":"Tú: vas a hacer.","optionNotes":[null,"Va is for él, ella, usted.","Voy is for yo.","Vais is for vosotros."]},{"id":"a1-verbs-ir-a-infinitive-q3","type":"multiple-choice","kind":"form","prompt":"Nosotros vamos a ___ a las ocho.","options":["salimos","salir","salgo","saliendo"],"correct":1,"explanation":"After ir a comes the infinitive: vamos a salir.","optionNotes":["After a, use the infinitive.",null,"Salgo is a conjugated form.","Spanish uses the infinitive here, not -ndo."]},{"id":"a1-verbs-ir-a-infinitive-q4","type":"multiple-choice","kind":"meaning","prompt":"“Vamos a empezar” can mean…","options":["We started.","Let's start.","We always start.","Start!"],"correct":1,"explanation":"Vamos a + infinitive can mean “let's”.","optionNotes":["That would be a past tense.",null,"That would be siempre empezamos.","That is an order to one person."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-present-irregular"] = {"version":1,"id":"a1-verbs-present-irregular","topic":"a1-verbs-present-irregular","level":"A1","title":"Stop: irregular verbs","passScore":3,"items":[{"id":"a1-verbs-present-irregular-q1","type":"multiple-choice","kind":"form","prompt":"Yo ___ un café, por favor.","options":["quero","quiero","queremos","quiere"],"correct":1,"explanation":"Querer changes e → ie: yo quiero.","optionNotes":["Querer changes the stem: quiero.",null,"Queremos is for nosotros.","Quiere is for él, ella, usted."]},{"id":"a1-verbs-present-irregular-q2","type":"multiple-choice","kind":"form","prompt":"Nosotros no ___ venir mañana.","options":["puedemos","pueden","podemos","puedo"],"correct":2,"explanation":"No stem change in nosotros: podemos.","optionNotes":["Nosotros keeps the o: podemos.","Pueden is for ellos.",null,"Puedo is for yo."]},{"id":"a1-verbs-present-irregular-q3","type":"multiple-choice","kind":"form","prompt":"Los sábados yo ___ la comida.","options":["hago","hace","haco","hacemos"],"correct":0,"explanation":"The yo form of hacer is hago.","optionNotes":[null,"Hace is for él, ella, usted.","The yo form ends in -go: hago.","Hacemos is for nosotros."]},{"id":"a1-verbs-present-irregular-q4","type":"multiple-choice","kind":"form","prompt":"¿___ (tú) a la playa mañana?","options":["Voy","Vas","Va","Vais"],"correct":1,"explanation":"Ir: voy, vas, va… The tú form is vas.","optionNotes":["Voy is for yo.",null,"Va is for él, ella, usted.","Vais is for vosotros."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-present-regular"] = {"version":1,"id":"a1-verbs-present-regular","topic":"a1-verbs-present-regular","level":"A1","title":"Stop: present tense","passScore":3,"items":[{"id":"a1-verbs-present-regular-q1","type":"multiple-choice","kind":"form","prompt":"Nosotros ___ en Valencia.","options":["vivemos","vivimos","viven","vivo"],"correct":1,"explanation":"Vivir is an -ir verb: nosotros vivimos.","optionNotes":["-ir verbs end in -imos, not -emos.",null,"Viven is for ellos.","Vivo is for yo."]},{"id":"a1-verbs-present-regular-q2","type":"multiple-choice","kind":"form","prompt":"¿Tú ___ inglés?","options":["hablas","habla","hablo","hablan"],"correct":0,"explanation":"The tú ending of -ar verbs is -as: hablas.","optionNotes":[null,"Habla is for él, ella and usted.","Hablo is for yo.","Hablan is for ellos."]},{"id":"a1-verbs-present-regular-q3","type":"multiple-choice","kind":"form","prompt":"Mi padre ___ en un hospital.","options":["trabajo","trabajas","trabajan","trabaja"],"correct":3,"explanation":"Mi padre = él: trabaja.","optionNotes":["Trabajo is for yo.","Trabajas is for tú.","Trabajan is for ellos.",null]},{"id":"a1-verbs-present-regular-q4","type":"multiple-choice","kind":"form","prompt":"Ellos no ___ carne.","options":["comen","come","comemos","comes"],"correct":0,"explanation":"Ellos: comen. No goes before the verb.","optionNotes":[null,"Come is for one person.","Comemos is for nosotros.","Comes is for tú."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-reflexive-routine"] = {"version":1,"id":"a1-verbs-reflexive-routine","topic":"a1-verbs-reflexive-routine","level":"A1","title":"Stop: daily routine","passScore":3,"items":[{"id":"a1-verbs-reflexive-routine-q1","type":"multiple-choice","kind":"form","prompt":"Yo ___ levanto a las siete.","options":["se","te","me","nos"],"correct":2,"explanation":"Yo takes the pronoun me: me levanto.","optionNotes":["Se is for él, ella, ellos.","Te is for tú.",null,"Nos is for nosotros."]},{"id":"a1-verbs-reflexive-routine-q2","type":"multiple-choice","kind":"form","prompt":"Mis hijos ___ acuestan a las nueve.","options":["se","les","me","os"],"correct":0,"explanation":"Ellos takes se: se acuestan.","optionNotes":[null,"Les is not a reflexive pronoun.","Me is for yo.","Os is for vosotros."]},{"id":"a1-verbs-reflexive-routine-q3","type":"multiple-choice","kind":"form","prompt":"Yo ___ a las once.","options":["me acosto","me acuesto","acuesto","se acuesta"],"correct":1,"explanation":"Acostarse changes o → ue and needs me: me acuesto.","optionNotes":["The stem changes: acuesto.",null,"The reflexive pronoun me is missing.","Se acuesta is for él or ella."]},{"id":"a1-verbs-reflexive-routine-q4","type":"multiple-choice","kind":"form","prompt":"Me lavo ___ dientes.","options":["mis","los","tus","sus"],"correct":1,"explanation":"With body parts Spanish uses the article: me lavo los dientes.","optionNotes":["The pronoun me already says whose teeth; use los.",null,"Tus would mean your teeth.","Sus would mean his, her, their or your (usted) teeth; with body parts use los."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-ser-vs-estar-basics"] = {"version":1,"id":"a1-verbs-ser-vs-estar-basics","topic":"a1-verbs-ser-vs-estar-basics","level":"A1","title":"Stop: ser or estar","passScore":3,"items":[{"id":"a1-verbs-ser-vs-estar-basics-q1","type":"multiple-choice","kind":"form","prompt":"Madrid ___ en el centro de España.","options":["es","está","hay","son"],"correct":1,"explanation":"Location of places takes estar: Madrid está en el centro.","optionNotes":["Location takes estar, not ser.",null,"Hay is for something new, not a named city.","Madrid is singular."]},{"id":"a1-verbs-ser-vs-estar-basics-q2","type":"multiple-choice","kind":"form","prompt":"La fiesta ___ en casa de Rosa.","options":["está","hay","es","estás"],"correct":2,"explanation":"Where an event takes place uses ser: la fiesta es en casa de Rosa.","optionNotes":["Events take ser for their place.","Hay would need un / una (hay una fiesta).",null,"Estás is for tú."]},{"id":"a1-verbs-ser-vs-estar-basics-q3","type":"multiple-choice","kind":"meaning","prompt":"“Los niños están aburridos” means…","options":["The children are boring.","The children are bored.","The children are tired.","The children are rich."],"correct":1,"explanation":"Aburrido with estar means bored; with ser it means boring.","optionNotes":["Boring would be son aburridos.",null,"Tired is cansados.","Rich is ricos."]},{"id":"a1-verbs-ser-vs-estar-basics-q4","type":"multiple-choice","kind":"form","prompt":"Mi hermana ___ médica.","options":["está","es","hay","está una"],"correct":1,"explanation":"A job takes ser, without un / una: es médica.","optionNotes":["Jobs take ser.",null,"Hay means “there is”.","Jobs take ser and no article."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-ser"] = {"version":1,"id":"a1-verbs-ser","topic":"a1-verbs-ser","level":"A1","title":"Stop: ser","passScore":3,"items":[{"id":"a1-verbs-ser-q1","type":"multiple-choice","kind":"form","prompt":"Nosotros ___ de Argentina.","options":["son","somos","sois","es"],"correct":1,"explanation":"The nosotros form of ser is somos.","optionNotes":["Son is for ellos, ellas and ustedes.",null,"Sois is for vosotros.","Es is for él, ella and usted."]},{"id":"a1-verbs-ser-q2","type":"multiple-choice","kind":"form","prompt":"Mi hermano ___ médico.","options":["es un","está","es","son"],"correct":2,"explanation":"A job after ser has no article: Es médico.","optionNotes":["No un before a job on its own.","Jobs take ser, not estar.",null,"Mi hermano is one person: es."]},{"id":"a1-verbs-ser-q3","type":"multiple-choice","kind":"form","prompt":"How do you say “I'm 30 years old”?","options":["Soy 30 años.","Estoy 30 años.","Soy de 30 años.","Tengo 30 años."],"correct":3,"explanation":"Age takes tener in Spanish: Tengo 30 años.","optionNotes":["Ser is not used for age.","Estar is not used for age.","Ser de is for origin, not age.",null]},{"id":"a1-verbs-ser-q4","type":"multiple-choice","kind":"form","prompt":"¿___ (tú) estudiante?","options":["Eres","Es","Soy","Sois"],"correct":0,"explanation":"The tú form of ser is eres.","optionNotes":[null,"Es is for él, ella and usted.","Soy is for yo.","Sois is for vosotros."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-verbs-tener"] = {"version":1,"id":"a1-verbs-tener","topic":"a1-verbs-tener","level":"A1","title":"Stop: tener","passScore":3,"items":[{"id":"a1-verbs-tener-q1","type":"multiple-choice","kind":"form","prompt":"¿Cuántos años ___ tu hermano?","options":["es","tiene","tienes","está"],"correct":1,"explanation":"Age takes tener; tu hermano is él: tiene.","optionNotes":["Age is not ser in Spanish.",null,"Tienes is for tú; tu hermano is él.","Age is not estar."]},{"id":"a1-verbs-tener-q2","type":"multiple-choice","kind":"form","prompt":"Nosotros ___ dos hijos.","options":["tienemos","tenemos","tienen","tengo"],"correct":1,"explanation":"In the nosotros form the stem does not change: tenemos.","optionNotes":["The stem stays ten- in the nosotros form.",null,"Tienen is for ellos.","Tengo is for yo."]},{"id":"a1-verbs-tener-q3","type":"multiple-choice","kind":"meaning","prompt":"How do you say “I'm cold”?","options":["Estoy frío.","Soy frío.","Tengo frío.","Hago frío."],"correct":2,"explanation":"The feeling of the body is tener: tengo frío.","optionNotes":["How your body feels takes tener, not estar.","Soy frío means “I'm a cold person” (unfriendly).",null,"Hace frío is for the weather; hago frío is wrong."]},{"id":"a1-verbs-tener-q4","type":"multiple-choice","kind":"form","prompt":"Tengo ___ hambre.","options":["mucho","mucha","muchos","muy"],"correct":1,"explanation":"Hambre is feminine (el hambre, like el agua), so “very” is mucha: tengo mucha hambre.","optionNotes":["Hambre is feminine.",null,"Hambre is singular.","Muy goes with adjectives, not nouns."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-vocabulary-family-people"] = {"version":1,"id":"a1-vocabulary-family-people","topic":"a1-vocabulary-family-people","level":"A1","title":"Stop: family and people","passScore":3,"items":[{"id":"a1-vocabulary-family-people-q1","type":"multiple-choice","kind":"meaning","prompt":"The mother of your mother is your ___.","options":["tía","prima","abuela","hija"],"correct":2,"explanation":"Your mother's mother is your grandmother: la abuela.","optionNotes":["La tía is your aunt.","La prima is your cousin.",null,"La hija is a daughter."]},{"id":"a1-vocabulary-family-people-q2","type":"multiple-choice","kind":"meaning","prompt":"“Mis padres” means…","options":["my relatives","my parents","my fathers only","my brothers"],"correct":1,"explanation":"Los padres usually means the father and the mother: parents.","optionNotes":["Relatives are parientes.",null,"Los padres is used for both parents.","Brothers are hermanos."]},{"id":"a1-vocabulary-family-people-q3","type":"multiple-choice","kind":"form","prompt":"Mi hermana es ___.","options":["alta","alto","altos","altas"],"correct":0,"explanation":"The adjective agrees with hermana: alta.","optionNotes":[null,"Alto is masculine.","Hermana is singular.","Hermana is singular."]},{"id":"a1-vocabulary-family-people-q4","type":"multiple-choice","kind":"form","prompt":"Mi abuelo tiene noventa años. Es ___. (the polite word for “old”)","options":["viejo","bajo","joven","mayor"],"correct":3,"explanation":"Mayor is the polite word: Mi abuelo es mayor.","optionNotes":["Viejo can sound rude about people.","Bajo means short.","Joven means young.",null]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-vocabulary-food-shopping"] = {"version":1,"id":"a1-vocabulary-food-shopping","topic":"a1-vocabulary-food-shopping","level":"A1","title":"Stop: food and prices","passScore":3,"items":[{"id":"a1-vocabulary-food-shopping-q1","type":"multiple-choice","kind":"form","prompt":"¿Cuánto ___ las manzanas?","options":["cuesta","cuestan","costan","cuesto"],"correct":1,"explanation":"Las manzanas is plural: cuestan (o → ue).","optionNotes":["Cuesta is for one thing.",null,"Costar changes o → ue: cuestan.","Cuesto would mean “I cost”."]},{"id":"a1-vocabulary-food-shopping-q2","type":"multiple-choice","kind":"form","prompt":"Un kilo ___ tomates, por favor.","options":["de","con","por","en"],"correct":0,"explanation":"Amounts need de: un kilo de tomates.","optionNotes":[null,"Con means “with”.","Por is not used for amounts.","En means “in”; amounts need de."]},{"id":"a1-vocabulary-food-shopping-q3","type":"multiple-choice","kind":"meaning","prompt":"Which word is a drink?","options":["el queso","el zumo","el pollo","el pan"],"correct":1,"explanation":"El zumo (Spain) / el jugo (Latin America) is juice.","optionNotes":["El queso is cheese.",null,"El pollo is chicken.","El pan is bread."]},{"id":"a1-vocabulary-food-shopping-q4","type":"multiple-choice","kind":"form","prompt":"___ agua está fría.","options":["La","Los","El","Las"],"correct":2,"explanation":"Agua is feminine but takes el in the singular: el agua.","optionNotes":["A feminine noun with a stressed a- takes el.","Agua is singular here.",null,"Agua is singular here."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-vocabulary-home-city"] = {"version":1,"id":"a1-vocabulary-home-city","topic":"a1-vocabulary-home-city","level":"A1","title":"Stop: home and town","passScore":3,"items":[{"id":"a1-vocabulary-home-city-q1","type":"multiple-choice","kind":"meaning","prompt":"Where do you sleep?","options":["en la cocina","en el dormitorio","en el baño","en la calle"],"correct":1,"explanation":"You sleep in the bedroom: el dormitorio.","optionNotes":["La cocina is the kitchen.",null,"El baño is the bathroom.","La calle is the street."]},{"id":"a1-vocabulary-home-city-q2","type":"multiple-choice","kind":"meaning","prompt":"Where do you borrow books?","options":["en la librería","en la farmacia","en el banco","en la biblioteca"],"correct":3,"explanation":"A library is la biblioteca; la librería is a bookstore.","optionNotes":["La librería is a bookstore, where you buy books.","La farmacia is the pharmacy.","El banco is the bank.",null]},{"id":"a1-vocabulary-home-city-q3","type":"multiple-choice","kind":"form","prompt":"La farmacia está al lado ___ banco.","options":["de","del","de la","al"],"correct":1,"explanation":"Al lado de + el banco = al lado del banco.","optionNotes":["De + el joins into del.",null,"Banco is masculine.","Al is a + el."]},{"id":"a1-vocabulary-home-city-q4","type":"multiple-choice","kind":"form","prompt":"___ un parque cerca de mi casa.","options":["Está","Hay","Es","Tiene"],"correct":1,"explanation":"Something new (un parque) takes hay.","optionNotes":["Está needs a known thing: el parque está…",null,"Ser is not used for where things are.","Tiene needs a subject who has it."]}]};
(LM.QUIZZES = LM.QUIZZES || {})["a1-vocabulary-numbers-days-months"] = {"version":1,"id":"a1-vocabulary-numbers-days-months","topic":"a1-vocabulary-numbers-days-months","level":"A1","title":"Stop: numbers, days, months","passScore":3,"items":[{"id":"a1-vocabulary-numbers-days-months-q1","type":"multiple-choice","kind":"form","prompt":"How do you write 22?","options":["veinte y dos","veintidós","veintedos","dos y veinte"],"correct":1,"explanation":"21–29 are one word, and 22 has an accent: veintidós.","optionNotes":["21–29 are written as one word.",null,"The word starts with veinti-, not veinte-.","The tens come first."]},{"id":"a1-vocabulary-numbers-days-months-q2","type":"multiple-choice","kind":"form","prompt":"How do you say “on Monday”?","options":["en el lunes","en lunes","el lunes","los lunes"],"correct":2,"explanation":"With days there is no word for “on”: el lunes. Los lunes means “on Mondays”, every week.","optionNotes":["Spanish has no en with days.","Spanish has no en with days, and it needs el.",null,"Los lunes means “on Mondays” (every Monday)."]},{"id":"a1-vocabulary-numbers-days-months-q3","type":"multiple-choice","kind":"meaning","prompt":"Which number is cuarenta y cinco?","options":["54","35","14","45"],"correct":3,"explanation":"Cuarenta is 40 and cinco is 5: 45.","optionNotes":["54 is cincuenta y cuatro.","35 is treinta y cinco.","14 is catorce.",null]},{"id":"a1-vocabulary-numbers-days-months-q4","type":"multiple-choice","kind":"meaning","prompt":"Mi cumpleaños es en ___. (My birthday is in August.)","options":["agosto","julio","abril","el agosto"],"correct":0,"explanation":"August is agosto, written with a small letter and without an article after en.","optionNotes":[null,"Julio is July.","Abril is April.","After en, a month has no article."]}]};
